mod solution;

fn main() {
    let cases = [
    (r#"matrix=[[0,3,10],[inf,0,2],[inf,inf,0]]"#, r#"5"#),
    (r#"matrix=[[0,7,2],[inf,0,1],[inf,inf,0]]"#, r#"2"#),
    (r#"
matrix=[[0,7,2],[inf,0,1],[inf,inf,0]]
"#, r#"2"#),
    (r#"  
matrix=[[0,3,10],[inf,0,2],[inf,inf,0]]
  "#, r#"5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS floyd-warshall");
}
